class Solution:
    def uniqueMiddle(self, nums):
        mid = nums[len(nums) // 2]
        return sum(x == mid for x in nums) == 1

c.cpp:
class Solution {
public:
    bool uniqueMiddle(vector<int>& nums) {
        int mid = nums[nums.size() / 2];
        int cnt = 0;
        for (int x : nums) if (x == mid) cnt++;
        return cnt == 1;
    }
};

